5355\u72ec\u6d88\u878d\u7684\u56e0\u5b50**\uff08\u53cc\u5411\u957f\u5377\u79ef\uff09\uff0c\u800c\u4e0d\u53ea\u662f\"B \u7684\u540d\u5b57\"\u3002\n\n\u9700\u8981\u63d0\u8bf7\u6f84\u6e05\u7684**\u524d\u63d0\u98ce\u9669\uff08\u5173\u952e\uff09**\uff1a\u636e\u6211\u6240\u77e5\u7684\u6807\u51c6 SiT\uff08Scalable Interpolant Transformer\uff0c\u6d41\u5339\u914d/\u6269\u6563\u56fe\u50cf\u751f\u6210\uff0cDiT \u5f0f adaLN \u6ce8\u5165\u65f6\u95f4\u6b65 t\uff09\u5e76\u4e0d\u5b58\u5728\u4e00\u4e2a\u72ec\u7acb\u7684\"\u65f6\u95f4\u6ce8\u610f\u529b\u6a21\u5757\"\u2014\u2014\u6ce8\u610f\u529b\u662f\u5728 patch token \u4e0a\u505a\u7a7a\u95f4\u6df7\u5408\uff0ct \u901a\u8fc7 adaLN/\u65f6\u95f4\u5d4c\u5165\u6ce8\u5165\u3002\u56e0\u6b64\"\u66ff\u6362\u65f6\u95f4\u6ce8\u610f\u529b\"\u5b58\u5728\u4e09\u79cd\u53ef\u80fd\u8bfb\u6cd5\uff0c\u6211\u6253\u7b97\u628a\u5b83\u4eec\u4f5c\u4e3a\u9700\u8981 researcher \u786e\u8ba4\u7684\u5206\u652f\uff1a\n\n- **R1**\uff1a\u5757\u5185\u5e8f\u5217\u6df7\u5408\u6ce8\u610f\u529b \u2192 \u975e\u56e0\u679c Hyena\uff08t \u4ecd\u8d70 adaLN\uff09\u3002\u8fd9\u662f\u6700\u53ef\u5b9e\u65bd\u7684\u8bfb\u6cd5\u3002\n- **R2**\uff1a\u786e\u5b9e\u5b58\u5728\u6309\u65f6\u95f4\u6b65/\u5e27\u6392\u5217\u7684\"\u65f6\u95f4\u8f74\u6ce8\u610f\u529b\"\uff08\u628a\u8f68\u8ff9\u6309\u65f6\u95f4\u987a\u5e8f token \u5316\uff09\u2192 \u6362\u6210\u53cc\u5411 Hyena\u3002\u8fd9\u662f\u552f\u4e00\u8ba9\"\u8f68\u8ff9/\u591a\u65f6\u95f4\u5c3a\u5ea6\"\u8bed\u4e49\u81ea\u7136\u7684\u8bfb\u6cd5\u3002\n- **R3**\uff1a\u66ff\u6362\u7684\u662f\u65f6\u95f4\u6761\u4ef6\u901a\u8def\uff08\u5bf9 t \u5e8f\u5217\u505a Hyena \u6df7\u5408\uff09\u3002\n\n\u540c\u6837\uff0c\"trajectories\"\u6709\u4e24\u79cd\u53ef\u80fd\u6307\u4ee3\uff1a(a) \u751f\u6210\u6837\u672c\u672c\u8eab\u5c31\u662f\u65f6\u95f4\u5e8f\u5217/\u89c6\u9891/\u52a8\u529b\u7cfb\u7edf\u8f68\u8ff9\uff1b(b) \u6d41\u6a21\u578b\u7684\u91c7\u6837\uff08ODE/\u79ef\u5206\uff09\u8f68\u8ff9\u3002\u82e5\u662f (b)\uff0c\"\u591a\u65f6\u95f4\u5c3a\u5ea6\u52a8\u529b\u5b66\u4e00\u81f4\u6027\"\u7684\u8bf4\u6cd5\u57fa\u672c\u4e0d\u9002\u7528\uff0c\u95ee\u9898\u53ef\u80fd\u9700\u8981\u91cd\u6784\u3002\u6211\u5efa\u8bae\u5728\u8bbe\u8ba1\u4e2d\u628a **R1+R2 \u7684\u7ec4\u5408\u5b9e\u73b0**\uff08\u540c\u4e00\u4ee3\u7801\u8def\u5f84\u65e2\u80fd\u5728\u56fe\u50cf token \u4e0a\u951a\u5b9a\u3001\u53c8\u80fd\u5728\u65f6\u95f4\u5e8f\u5217\u4e0a\u4e3b\u5f20\u8f68\u8ff9\u8bed\u4e49\uff09\u4f5c\u4e3a\u9ed8\u8ba4\uff0c\u7b49 setup_4/setup_5 \u6f84\u6e05\u540e\u6536\u655b\u3002\n\n\u56e0\u6b64\u5b9e\u9a8c\u8bbe\u8ba1\u7684\u9aa8\u67b6\u662f **2\u00d7\uff08\u56e0\u679c\u6027\uff09\u00d7\uff08\u7b97\u5b50\u7c7b\uff09\u56e0\u5b50\u8bbe\u8ba1 + \u957f\u5ea6\u5916\u63a8\u534f\u8bae + \u9884\u6ce8\u518c\u5224\u5b9a\u89c4\u5219**\uff0c\u4f7f\u7ed3\u8bba\u80fd\u5f52\u56e0\u5230\"\u975e\u56e0\u679c\u957f\u7a0b\u6df7\u5408\"\u8fd9\u4e00\u5177\u4f53\u673a\u5236\uff0c\u800c\u4e0d\u662f\"\u6362\u4e86\u4e2a\u5e93\"\u3002\n\n## 3) \u5b9e\u9a8c\u8bbe\u8ba1\u7ec4\u7ec7\u65b9\u5f0f\uff08\u6846\u67b6\uff1b\u7ec6\u8282\u5f85\u6279\u51c6\u540e\u5c55\u5f00\u4e3a\u5b8c\u6574 result\uff09\n\n**A. \u6570\u636e\uff08\u4e09\u5c42\uff0c\u907f\u514d\u53ea\u5728\u5408\u6210\u6570\u636e\u4e0a\u6210\u7acb\uff09**\n- T1 \u5408\u6210\u591a\u5c3a\u5ea6\u52a8\u529b\u7cfb\u7edf\uff08\u4e3b\uff09\uff1a\u591a\u9891\u7387\u8026\u5408\u632f\u5b50\uff08\u9891\u7387\u8de8\u5ea6 \u22653 \u4e2a\u6570\u91cf\u7ea7\uff09\u3001\u5468\u671f+\u6df7\u6c8c\u6df7\u5408\uff08Lorenz-96 / R\u00f6ssler \u5e26\u5c3a\u5ea6\u5206\u79bb\uff09\u3001\u591a\u5c3a\u5ea6 SDE\uff1b\u5916\u52a0\"\u957f\u7a0b\u4e00\u81f4\u6027\u63a2\u9488\"\uff1a\u4e00\u4e2a\u5168\u5c40\u9690\u53d8\u91cf\u5728\u5f00\u5934\u7f16\u7801\u3001\u5fc5\u987b\u5728 16k\u201364k token \u540e\u4ecd\u88ab\u4fdd\u6301\uff08\u53ef\u63a7\u7684\u68c0\u7d22\u5f0f\u4efb\u52a1\uff09\u3002\n- T2 \u771f\u5b9e\u957f\u65f6\u5e8f\u6570\u636e\uff08\u8bb8\u53ef\u5141\u8bb8\u4e0b\uff09\uff1a\u7269\u7406/\u8fd0\u52a8\u6355\u6349\u6216\u89c6\u9891\u6f5c\u53d8\u91cf\u5e8f\u5217\uff0c\u9a8c\u8bc1\u7ed3\u8bba\u4e0d\u662f\u5408\u6210\u6570\u636e\u4f2a\u5f71\u3002\n- T3 SiT \u539f\u751f\u56fe\u50cf\u751f\u6210\uff08\u951a\u5b9a\uff09\uff1a\u786e\u8ba4\u7b97\u5b50\u66ff\u6362\u4e0d\u7834\u574f\u6807\u51c6\u57fa\u51c6\uff08FID \u4e0d\u9000\u5316\uff09\uff0c\u4f7f B \u76f8\u5bf9 A \u7684\"\u8f68\u8ff9\u4f18\u52bf\"\u4e0d\u662f\u4ee5\u57fa\u7840\u80fd\u529b\u53d7\u635f\u4e3a\u4ee3\u4ef7\u3002\n\n**B. \u7b97\u5b50\u56e0\u5b50\uff08\u552f\u4e00\u88ab\u64cd\u7eb5\u7684\u56e0\u7d20\uff0c\u5176\u4f59\u5168\u90e8\u5bf9\u9f50\uff09**\n- A\uff1aSiT \u539f\u6ce8\u610f\u529b\uff08\u540c\u4f4d\u7f6e\u7f16\u7801\u65b9\u6848\uff09\uff1bB\uff1a\u975e\u56e0\u679c Hyena\uff08order-N \u9690\u5f0f\u957f\u5377\u79ef\uff0c\u53cc\u5411\u6838\uff09\uff1b\n- \u63a7\u5236\u81c2\uff1a\u56e0\u679c Hyena\uff08\u9694\u79bb\"\u975e\u56e0\u679c\"\u8d21\u732e\uff09\u3001\u77ed\u6df1\u5ea6\u5377\u79ef/\u5c40\u90e8\u6838\uff08\u9694\u79bb\"\u5168\u5c40\u6df7\u5408\"\u8d21\u732e\uff09\u3001\u5355\u5934\u7ebf\u6027\u6ce8\u610f\u529b\u3001\u957f\u5ea6\u6761\u4ef6 MLP\uff08\u4e0d\u5916\u63a8\u7684\u8d1f\u5bf9\u7167\uff09\u3002\n- \u4e25\u683c\u5bf9\u9f50\uff1a\u53c2\u6570\u91cf/FLOPs/\u4f18\u5316\u5668/\u6b65\u6570/\u6570\u636e\u987a\u5e8f/\u79cd\u5b50\u96c6\u5408/\u65f6\u95f4\u6761\u4ef6\u8def\u5f84/tokenizer \u4e0e patch \u5316\u5168\u90e8\u76f8\u540c\uff1b\u4f4d\u7f6e\u7f16\u7801\u65b9\u6848\u4f5c\u4e3a\u4ea4\u53c9\u56e0\u5b50\uff08RoPE \u53ca\u5176\u957f\u5ea6\u7f29\u653e / ALiBi / \u65e0\uff09\uff0c\u907f\u514d\u628a\"\u4f4d\u7f6e\u7f16\u7801\u5916\u63a8\u9000\u5316\"\u8bef\u5224\u4e3a\u7b97\u5b50\u5dee\u5f02\u3002\n\n**C. \"\u6781\u957f\"\u4e0e\"\u4e00\u81f4\"\u7684\u53ef\u64cd\u4f5c\u6d4b\u91cf**\n- \u6781\u957f\uff1a\u8bad\u7ec3\u957f\u5ea6 L_train \u56fa\u5b9a\uff0c\u8bc4\u6d4b L/L_train \u2208 {1,2,4,8,16,32,64}\uff1b**\u4e3b\u5224\u5b9a\u4e3a\u5916\u63a8\u66f2\u7ebf\u800c\u975e\u5355\u70b9**\uff1b\u9884\u6ce8\u518c\"\u6781\u957f\"\u9608\u503c\uff08\u4f8b\u5982 \u226516\u00d7 L_train \u4e14\u5728 \u22652 \u4e2a\u6570\u91cf\u7ea7\u7684\u6ede\u540e\u4e0a\u4ecd\u5b58\u5728\u53ef\u6d4b\u7684\u5730\u9762\u771f\u503c\u81ea\u76f8\u5173\uff09\uff0c\u5e76\u540c\u65f6\u7528\u7269\u7406\u65f6\u95f4\u5355\u4f4d\u62a5\u544a\u3002\n- \u4e00\u81f4\u6027\uff084 \u7c7b\u4e92\u8865\u6307\u6807\uff0c\u9632\u6b62\u5355\u4e00\u6307\u6807\u88ab\"\u8fc7\u5e73\u6ed1\"\u4f5c\u5f0a\uff09\uff1a\n  1. \u8bef\u5dee\u589e\u957f\uff1ateacher-forcing vs \u81ea\u7531\u8fd0\u884c rollouts \u7684\u6563\u5ea6\u66f2\u7ebf\u3001\u8bef\u5dee\u589e\u957f\u6307\u6570\u3001\u8d85\u51fa\u5bb9\u5dee \u03b5 \u7684\u65f6\u95f4\uff08horizon-to-failure\uff09\uff1b\n  2. \u7a97\u53e3\u5206\u5e03\u4e00\u81f4\u6027\uff1a\u957f rollout \u5206\u7a97 vs \u771f\u5b9e\u7a97\u53e3\u7684\u5206\u5e03\u8ddd\u79bb\uff08\u80fd\u91cf\u8ddd\u79bb/Wasserstein\uff1b\u56fe\u50cf/\u89c6\u9891\u7528 FID/FVD \u6216\u7a97\u53e3\u771f\u5b9e\u6027\u5224\u522b\u5668\uff09\u3001\u4e0d\u53d8\u91cf/\u80fd\u91cf\u6f02\u79fb\uff1b\n  3. \u5168\u5c40\u81ea\u6d3d\uff1a\u540c\u4e00\u6761\u4ef6/\u5168\u5c40\u9690\u53d8\u91cf\u4e0b\u975e\u91cd\u53e0\u7a97\u53e3\u95f4\u7684\u4e00\u81f4\u5ea6\uff08cross-window consistency\u3001\u76f8\u4f4d\u9501\u5b9a\u3001motif \u590d\u73b0\u7387\uff09\uff1b\n  4. \u957f\u5ea6-\u635f\u5931\u6807\u5ea6\uff1abits/token \u6216 flow-matching loss \u968f\u957f\u5ea6\u7684\u53d8\u5316\u7387\uff08\u662f\u5426\u51fa\u73b0\u957f\u5ea6\u9000\u5316\u62d0\u70b9\uff09\u3002\n\n**D. \"\u591a\u65f6\u95f4\u5c3a\u5ea6\"\u7684\u53ef\u64cd\u4f5c\u6d4b\u91cf**\n- \u591a\u6ede\u540e\u81ea\u76f8\u5173/\u81ea\u534f\u65b9\u5dee\u8bef\u5dee\uff0c\u5728 log \u95f4\u9694\u6ede\u540e\u7f51\u683c\uff0810^0\u201310^3.5\uff09\u4e0a\u9010\u6ede\u540e\u6bd4\u8f83\uff1b\n- \u500d\u9891\u7a0b\u5c0f\u6ce2/STFT \u80fd\u91cf\u8c31 vs \u5730\u9762\u771f\u503c\u8c31\u7684\u8ddd\u79bb\uff08\u8c31 Wasserstein\uff09\uff0c\u5e76\u62a5\u544a\u6bcf\u9891\u5e26 explained-variance\uff08\u68c0\u6d4b\"\u584c\u5230\u6162\u6a21\u6001\"\u6216\"\u584c\u5230\u5feb\u566a\u58f0\"\uff09\uff1b\n- \u7ed3\u6784\u51fd\u6570\uff082 \u9636/4 \u9636\uff09\u5bf9\u6df7\u6c8c\u7c7b\u6570\u636e\uff1bDMD/Koopman \u7279\u5f81\u503c\u8c31\u4e0e**\u63a8\u65ad\u65f6\u95f4\u5c3a\u5ea6\u76f4\u65b9\u56fe**\uff0c\u68c0\u9a8c\"\u65f6\u95f4\u5c3a\u5ea6\u96c6\u5408\"\u662f\u5426\u88ab\u590d\u73b0\uff08\u800c\u975e\u5e73\u5747\u884c\u4e3a\u76f8\u4f3c\uff09\uff1b\n- \u591a\u6837\u6027/\u6a21\u5f0f\u584c\u7f29\u68c0\u67e5\u4e0e\u4e0a\u8ff0\u6307\u6807\u6210\u5bf9\u62a5\u544a\u3002\n\n**E. \u7edf\u8ba1\u4e0e\u5224\u5b9a\u89c4\u5219\uff08\u9884\u6ce8\u518c\uff09**\n- \u6bcf\u81c2 \u22653\u20135 \u79cd\u5b50\uff0c\u79cd\u5b50\u4f5c\u968f\u673a\u6548\u5e94\uff0cbootstrap/\u6df7\u5408\u6a21\u578b CI\uff1b\n- \u5224\u5b9a\"\u662f\"\u9700\u540c\u65f6\u6ee1\u8db3\uff1a(i) \u5728\u9884\u6ce8\u518c\u5916\u63a8\u957f\u5ea6\u4e0a\uff0cB \u5728\u4e3b\u7ec8\u70b9\uff08\u957f\u65f6\u7a0b\u4e00\u81f4\u6027\uff09\u4f18\u4e8e A \u8d85\u8fc7\u9884\u6ce8\u518c\u5e45\u5ea6\u4e14 CI \u4e0d\u91cd\u53e0\uff1b(ii) \u65f6\u95f4\u5c3a\u5ea6\u8c31\u6307\u6807\u4e0d\u9000\u5316\uff1b(iii) \u56e0\u679c Hyena \u4e0e\u5c40\u90e8\u6838\u63a7\u5236\u81c2\u663e\u793a\u589e\u76ca\u786e\u5b9e\u6765\u81ea\"\u975e\u56e0\u679c\u957f\u7a0b\u6df7\u5408\"\uff1b(iv) T3 \u6807\u51c6\u57fa\u51c6\u4e0d\u660e\u663e\u9000\u5316\u3002\u5426\u5219\u62a5\"\u5426/\u6df7\u5408/\u6761\u4ef6\u6027\u6210\u7acb\"\u3002\n- \u540c\u65f6\u62a5\u544a**\u7b49\u7b97\u529b**\u4e0e**\u7b49\u6b65\u6570**\u4e24\u5957 Pareto \u66f2\u7ebf\uff08Hyena \u5728\u957f\u5e8f\u5217\u4e0a\u6bcf token \u66f4\u4fbf\u5b9c\uff0c\u53ea\u62a5\u7b49\u6b65\u6570\u4f1a\u504f\u8892\uff09\u3002\n\n**F. \u5206\u6790\u8ba1\u5212**\uff1a\u4e3b\u7ec8\u70b9\u68c0\u9a8c \u2192 \u5916\u63a8\u66f2\u7ebf\u4e0e\u6807\u5ea6\u5f8b\u62df\u5408 \u2192 \u673a\u5236\u5f52\u56e0\u6d88\u878d\uff08\u56e0\u679c\u6027/order N/\u6838\u8870\u51cf\u521d\u59cb\u5316/\u95e8\u63a7/\u5f52\u4e00\u5316\uff09\u2192 \u654f\u611f\u6027\uff08Hyena \u8870\u51cf\u957f\u5ea6 vs \u6570\u636e\u65f6\u95f4\u5c3a\u5ea6\u7684\u5339\u914d\u7a0b\u5ea6\uff09\u2192 \u5931\u8d25\u6a21\u5f0f\u5b9a\u6027\u5206\u6790\uff08rollout \u7247\u6bb5\u3001\u8c31\u6b8b\u5dee\uff09\u3002\n\n**G. \u53ef\u884c\u6027\u8bf4\u660e\uff08\u8bda\u5b9e\u7248\uff09**\uff1a\u672c\u73af\u5883\uff08\u65e0 GPU/\u65e0\u7f51\u7edc/\u65e0 torch\uff09\u65e0\u6cd5\u8fd0\u884c\u771f\u5b9e\u8bad\u7ec3\u3002\u53ef\u6267\u884c\u90e8\u5206\uff1a\u7eaf Python \u5b9e\u73b0\u7684\u5408\u6210\u6570\u636e\u751f\u6210\u5668\u4e0e\u5168\u5957\u6307\u6807\u8ba1\u7b97\u5668\u7684\u6b63\u786e\u6027\u81ea\u68c0\uff08\u5728\u89e3\u6790\u53ef\u89e3\u7684\u632f\u5b50\u6570\u636e\u4e0a\u9a8c\u8bc1\u6307\u6807\u6570\u503c\u3001\u9a8c\u8bc1\u957f\u5ea6\u5916\u63a8\u8bc4\u6d4b\u811a\u672c\u3001\u9a8c\u8bc1\u975e\u56e0\u679c\u6838\u53cc\u5411\u7d22\u5f15\u4e0e\u8fb9\u754c/padding \u5b9e\u73b0\uff09\u3002\u771f\u5b9e\u5b9e\u9a8c\u9700 GPU \u96c6\u7fa4 + PyTorch/Hyena \u957f\u5377\u79ef\uff08\u6216 flash \u5f0f\u957f\u5377\u79ef\uff09\u73af\u5883\uff1b\u5b8c\u6574\u8bbe\u8ba1\u5c06\u7ed9\u51fa\u6bcf\u81c2\u6bcf\u79cd\u5b50\u7684 GPU-hour \u4f30\u7b97\u4e0e\u6700\u77ed\u53ef\u53d1\u8868\u914d\u7f6e\uff08\u4f8b\u5982 SiT-B/\u77ed\u8bad\u7ec3 + \u5355\u5c3a\u5ea6\u6570\u636e\u5148\u8dd1\u901a\uff09\u3002\n\n## 4) \u5047\u8bbe\u3001\u4e0d\u786e\u5b9a\u9879\u3001\u9700\u8981\u6f84\u6e05\u7684\u95ee\u9898\n\n**\u5047\u8bbe\uff08\u4e0e\u4efb\u52a1\u56fa\u5b9a\u8981\u6c42\u5206\u5f00\u58f0\u660e\uff09**\uff1aSiT \u6307 DiT \u5f0f adaLN \u65f6\u95f4\u6ce8\u5165\u7684\u53ef\u6269\u5c55\u63d2\u503c/\u6d41 Transformer\uff1b\"\u975e\u56e0\u679c Hyena\"= \u53cc\u5411\uff08\u5bf9\u79f0\u6216\u975e\u5bf9\u79f0\u3001\u975e\u4e25\u683c\u56e0\u679c\u63a9\u853d\uff09order-N \u9690\u5f0f\u957f\u5377\u79ef\uff1b\u4e24\u81c2\u9664\u88ab\u64cd\u7eb5\u56e0\u7d20\u5916\u5168\u90e8\u5bf9\u9f50\uff1b\"\u8f68\u8ff9\"\u6309\u6837\u672c\u65f6\u5e8f\u89e3\u91ca\u3002\n\n**\u4e0d\u786e\u5b9a\u9879/\u98ce\u9669**\uff1a(1) \u524d\u63d0\u98ce\u9669\u2014\u2014\u82e5 SiT \u65e0\"\u65f6\u95f4\u6ce8\u610f\u529b\"\uff0c\u95ee\u9898\u9700\u6309 R1/R2/R3 \u91cd\u6784\uff0c\u6211\u4f1a\u5728\u6700\u7ec8\u8bbe\u8ba1\u4e2d\u660e\u786e\u6807\u6ce8\uff1b(2) \u516c\u5e73\u6027\u98ce\u9669\u2014\u2014\u975e\u56e0\u679c B \u5728\u8bc4\u6d4b\u65f6\u662f\u5426\u88ab\u5141\u8bb8\u4f7f\u7528\u672a\u6765\u4e0a\u4e0b\u6587\uff0c\u5fc5\u987b\u4e0e A \u7684\u4e0a\u4e0b\u6587\u5047\u8bbe\u4e25\u683c\u4e00\u81f4\uff1b(3) \u6df7\u6dc6\u9879\u2014\u2014\u4f4d\u7f6e\u7f16\u7801\u5916\u63a8\u3001\u6838\u8870\u51cf\u521d\u59cb\u5316\u3001\u6bcf token \u7b97\u529b\u4e0d\u5bf9\u79f0\uff1b(4) \u6307\u6807\u6df7\u6dc6\u2014\u2014\u8c31\u7c7b\u6307\u6807\u504f\u7231\u8fc7\u5e73\u6ed1\u8f93\u51fa\uff1b(5) \u6570\u636e\u8bb8\u53ef\u4e0e\u53ef\u7528\u6027\u3002\n\n**\u6f84\u6e05\u95ee\u9898\uff08\u9884\u7b97 6\uff0c\u6309\u4f18\u5148\u7ea7\uff1b\u5efa\u8bae\u5148\u7b54 1\u20133\uff09**\n1. (setup_4) \u6e90\u6750\u6599\u4e2d\u7684\"\u65f6\u95f4\u6ce8\u610f\u529b\"\u5177\u4f53\u6307\u4ec0\u4e48\uff1aR1 \u5757\u5185\u5e8f\u5217\u6df7\u5408\u6ce8\u610f\u529b / R2 \u6309\u65f6\u95f4\u6b65\u7684\u65f6\u95f4\u8f74\u6ce8\u610f\u529b / R3 \u65f6\u95f4\u6761\u4ef6\u901a\u8def\uff1f\u6e90\u67b6\u6784\u662f\u5426\u771f\u7684\u5b58\u5728\u72ec\u7acb\u7684\u65f6\u95f4\u8f74\u6ce8\u610f\u529b\u6a21\u5757\uff1f\n2. (setup_4) \u6e90\u4e2d\"\u8f68\u8ff9\"\u6307\u751f\u6210\u6837\u672c\u7684\u65f6\u5e8f\u3001\u8fd8\u662f\u91c7\u6837/ODE \u8f68\u8ff9\uff1f\u6240\u7528\u6570\u636e\u6a21\u6001\u4e0e\u5e8f\u5217\u957f\u5ea6\u3001\"\u6781\u957f\"\u7684\u5177\u4f53\u91cf\u7ea7\uff08tokens \u4e0e\u7269\u7406\u65f6\u95f4\uff09\uff1f\n3. (setup_4) Hyena \u7684\u786e\u5207\u914d\u7f6e\uff1aorder N\u3001\u6838\u53c2\u6570\u5316\u4e0e\u8870\u51cf\u521d\u59cb\u5316\u3001\u95e8\u63a7\u3001\u53cc\u5411/\u975e\u56e0\u679c\u7684\u5177\u4f53\u5b9e\u73b0\u4e0e\u8fb9\u754c padding\u3001\u5f52\u4e00\u5316\u4e0e\u6b