import math, time, random
random.seed(0)
N = 16384
# three well-separated timescales (fast 4, medium 128, slow 4096 samples) + slow latent
sig = []
for n in range(N):
    v = (0.6*math.sin(2*math.pi*n/4.0)
         + 0.3*math.sin(2*math.pi*n/128.0 + 0.7)
         + 0.9*math.sin(2*math.pi*n/4096.0 + 1.3)
         + 0.2*math.exp(-((n % 4096)/4096.0*2*math.pi)))
    sig.append(v + random.gauss(0, 0.05))
mean = sum(sig)/N
x = [v-mean for v in sig]
var = sum(v*v for v in x)/N
t0=time.time()
lags = [int(round(10**(i/8.0))) for i in range(0, 30)]
acf = []
for k in sorted(set(l for l in lags if l < N)):
    c = sum(x[i]*x[i+k] for i in range(N-k))/(N-k)/var
    acf.append((k, round(c,3)))
t1=time.time()
# octave band energies via Goertzel (avoid O(N^2) DFT)
def band_energy(f0, f1, nb=16):
    e = 0.0
    for j in range(nb):
        f = f0*(f1/f0)**(j/(nb-1.0))
        w = 2*math.pi*f; cw = math.cos(w); coeff = 2*cw; s1=s2=0.0
        for v in x:
            s0 = v + coeff*s1 - s2; s2 = s1; s1 = s0
        e += (s1*s1 + s2*s2 - coeff*s1*s2)/ (N*N)
    return e
bands = [(1/8192.0, 1/1024.0), (1/1024.0, 1/64.0), (1/64.0, 1/2.0)]
be = [(round(b0*1000,3), round(b1*1000,3), round(band_energy(b0,b1),6)) for b0,b1 in bands]
t2=time.time()
print("N=%d var=%.4f" % (N, var))
print("ACF@lags sample:", acf[:6], "...", acf[-4:])
print("octave-band energies (cycles/sample x1000):", be)
print("acf_time=%.3fs band_time=%.3fs" % (t1-t0, t2-t1))
# detect timescale histogram from ACF peaks (crude, for design validation only)
peaks = [acf[i] for i in range(1,len(acf)-1) if acf[i][1] > acf[i-1][1] and acf[i][1] > acf[i+1][1]]
